effect.shader:
// k/255 pelo mais perto, montado nos bits do float: o valor exato que a textura de 8 bits devolve (o
// `floor(..)/255.0` vai pelo recíproco e erra o último bit — ver `am-color-balance.xml`).
float oitoBits(float k) {
    uint n = uint(k);
    if (n == 0u) return 0.0;
    if (n == 255u) return 1.0;
    int j = 0;                                                    // o bit mais alto de n
    for (int i = 1; i < 8; i++) if (n >= (1u << uint(i))) j = i;
    int e = 31 - j;
    uint q = ((n << uint(e)) + 127u) / 255u;                      // entre 2^23 e 2^24
    return uintBitsToFloat((uint(150 - e) << 23) + (q - 0x800000u));
}

vec3 oitoBits3(vec3 k) {
    return vec3(oitoBits(k.r), oitoBits(k.g), oitoBits(k.b));
}

vec3 linear(vec3 c) {
    return mix(c / 12.92, pow((c + 0.055) / 1.055, vec3(2.4)), step(vec3(0.04045), c));
}

vec3 srgb(vec3 l) {
    l = clamp(l, 0.0, 1.0);
    return mix(l * 12.92, 1.055 * pow(l, vec3(1.0 / 2.4)) - 0.055, step(vec3(0.0031308), l));
}

// Os bytes que um RT sRGB de 8 bits guarda para esta cor linear.
vec3 bytesSrgb(vec3 l) {
    return floor(srgb(l) * 255.0 + 0.5);
}

// O texel exato de uma imagem do tamanho da tela no pixel de pé (a linha 0 é a base, como nos RTs do Node): no
// buffer de camada (`acEntradaDePe` = 0, a linha 0 é o topo) a linha é espelhada. Lê a entrada para o RT de pé e o RT
// de pé para a saída — os dois espelhos se desfazem, e a conta do meio é a da tela.
vec4 texelDePe(highp sampler2D img) {
    ivec2 T = textureSize(img, 0);
    ivec2 p = ivec2(min(floor(acScreenNorm * vec2(T)), vec2(T) - 1.0));
    if (acEntradaDePe != 1) p.y = T.y - 1 - p.y;
    return texelFetch(img, p, 0);
}

// O programa do Node, conta por conta (o `_SourceTex` é o `camadaRt`, os parâmetros com os nomes do Nova).
// [vs_TEXCOORD0]: o UV do Node (cresce para cima). Sem a máscara interna: o ramo `_use_inner_mask` == 0.
vec4 mirror(vec2 vs_TEXCOORD0, vec2 _reflection_center) {
    // [_reflection_center]: no UV do Node (ver o `main`). O `_viewport_ratio` do `RCEffect::Render` é o
    // `acProporcaoDoNode`, feito na CPU como o Node faz. O Bool chega como o `SetGlobalInt` do Node: 0 ou 1.
    float _reflection_angle = reflectionAngle;
    int _invert = invert ? 1 : 0;
    vec2 _viewport_ratio = acProporcaoDoNode;
    vec4 u_xlat0;
    vec4 u_xlat1;
    bvec2 u_xlatb1;
    vec4 u_xlat2;
    vec2 u_xlat12;
    bvec2 u_xlatb12;
    vec2 u_xlat13;
    float u_xlat18;
    bool u_xlatb18;
    u_xlat0.xy = vs_TEXCOORD0.xy + vec2(-0.5, -0.5);
    u_xlat12.xy = _reflection_center.xy + vec2(-0.5, -0.5);
    u_xlat1.xy = u_xlat0.xy * vec2(_viewport_ratio.x, _viewport_ratio.y);
    u_xlat13.xy = vec2(vec2(_reflection_angle, _reflection_angle)) * vec2(0.0174532942, 360.0);
    u_xlat2.x = cos(u_xlat13.x);
    u_xlat13.x = sin((-u_xlat13.x));
    u_xlat2.xy = u_xlat2.xx * vec2(-0.5, 0.5);
    u_xlat2.zw = u_xlat13.xx * vec2(-0.5, 0.5);
    u_xlat2 = u_xlat12.xyxy * vec4(_viewport_ratio.x, _viewport_ratio.y, _viewport_ratio.x, _viewport_ratio.y) + u_xlat2.xzyw;
    u_xlat0.xy = u_xlat0.xy * vec2(_viewport_ratio.x, _viewport_ratio.y) + (-u_xlat2.xy);
    u_xlat12.xy = (-u_xlat2.xy) + u_xlat2.zw;
    u_xlat13.x = dot(u_xlat0.xy, u_xlat12.xy);
    u_xlat2.x = dot(u_xlat12.xy, u_xlat12.xy);
    u_xlat13.x = u_xlat13.x / u_xlat2.x;
    u_xlat0.xy = (-u_xlat13.xx) * u_xlat12.xy + u_xlat0.xy;
    u_xlatb12.x = u_xlat13.y>=(-u_xlat13.y);
    u_xlat12.xy = (u_xlatb12.x) ? vec2(360.0, 0.00277777785) : vec2(-360.0, -0.00277777785);
    u_xlat18 = u_xlat12.y * _reflection_angle;
    u_xlat18 = fract(u_xlat18);
    u_xlat12.x = u_xlat18 * u_xlat12.x;
    u_xlatb18 = 90.0<abs(u_xlat12.x);
    u_xlatb12.x = abs(u_xlat12.x)<270.0;
    u_xlatb12.x = u_xlatb12.x && u_xlatb18;
    u_xlat13.xy = (int(_invert) != 0) ? vec2(-1.0, 1.0) : vec2(1.0, -1.0);
    u_xlat12.x = (u_xlatb12.x) ? u_xlat13.y : u_xlat13.x;
    u_xlatb18 = abs(u_xlat0.y)<9.99999975e-05;
    u_xlat13.xy = u_xlat12.xx * (-u_xlat0.yx);
    u_xlat12.x = (u_xlatb18) ? u_xlat13.y : u_xlat13.x;
    u_xlat12.x = u_xlat12.x * 100000.0;
    u_xlat12.x = clamp(u_xlat12.x, 0.0, 1.0);
    u_xlat0.xy = u_xlat0.xy * u_xlat12.xx;
    u_xlat0.xy = (-u_xlat0.xy) * vec2(2.0, 2.0) + u_xlat1.xy;
    u_xlat0.xy = u_xlat0.xy / vec2(_viewport_ratio.x, _viewport_ratio.y);
    u_xlat0.xy = u_xlat0.xy + vec2(0.5, 0.5);
    u_xlatb12.xy = lessThan(u_xlat0.xyxy, vec4(0.0, 0.0, 0.0, 0.0)).xy;
    u_xlatb1.xy = lessThan(vec4(1.0, 1.0, 0.0, 0.0), u_xlat0.xyxx).xy;
    u_xlatb12.x = u_xlatb12.x || u_xlatb1.x;
    u_xlatb12.x = u_xlatb12.y || u_xlatb12.x;
    u_xlatb12.x = u_xlatb1.y || u_xlatb12.x;
    u_xlat1 = texture(camadaRt, u_xlat0.xy);
    u_xlat0.x = (u_xlatb12.x) ? 0.0 : 1.0;
    u_xlat0 = u_xlat0.xxxx * u_xlat1;
    return u_xlat0;
}

void main() {
    if (acPass == 0) {
        // A camada como o RT dela no Node: a cor em luz linear vezes o alfa, de pé; a GPU guarda em sRGB.
        vec4 c = texelDePe(inputImg);
        fragColor = vec4(linear(c.rgb) * c.a, c.a);
        return;
    }
    if (acPass == 1) {
        // O RT da camada está de pé: o UV do Node é o da tela, nos dois casos. O Centro chega na tela de pé (o UV do
        // Node) quando a entrada é de pé; no buffer de camada, no Y para baixo do buffer: vira 1 − Y.
        // `Blend One Zero`: a saída como está (o alvo sRGB de 8 bits prende, como o do Node).
        vec2 centro = acEntradaDePe == 1 ? reflectionCenter : vec2(reflectionCenter.x, 1.0 - reflectionCenter.y);
        fragColor = mirror(acScreenNorm, centro);
        return;
    }

    // Os bytes do RT de saída do Node (a GPU decodificou ao ler; codificar de novo devolve o byte guardado), de volta
    // à orientação da entrada.
    vec4 o = texelDePe(saidaRt);
    vec3 kc = bytesSrgb(o.rgb);
    float ka = floor(o.a * 255.0 + 0.5);
    if (ka <= 0.0) {
        fragColor = vec4(0.0);
        return;
    }
    if (ka >= 255.0) {
        fragColor = vec4(oitoBits3(kc), 1.0);
        return;
    }
    // O Nova guarda reto: a cor linear guardada dividida pelo alfa, de volta ao sRGB (acima de 1 fica em 1).
    float a = oitoBits(ka);
    fragColor = vec4(srgb(min(linear(oitoBits3(kc)) / a, vec3(1.0))), a);
}
